def gen(rng):
    L = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    def plate(la=L, da='0123456789'):
        return ''.join(rng.choice(la) for _ in range(3)) + ''.join(rng.choice(da) for _ in range(4))
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(ps)
    tests = [fmt(['ABC1234', 'AAA0006', 'ZZZ0000']), fmt(['BAA1111', 'AAB1111', 'AAA9999']), fmt(['AAA0000']), fmt(['ZZZ9999', 'ZZZ9999']), fmt(['AAA0003', 'AAA0030', 'AAA0300']), fmt(['ZZZ0000', 'AAA9999'])]
    for n in range(2, 10):
        for _ in range(2):
            tests.append(fmt([plate() for _ in range(n)]))
    for n in (5, 12):
        tests.append(fmt([plate('ABC', '0123') for _ in range(n)]))
    N = 10 ** 5
    tests.append(fmt([plate() for _ in range(N)]))
    tests.append(fmt([plate('XYZ', '9876') for _ in range(N)]))
    tests.append(fmt([plate('AB', '0123') for _ in range(N)]))
    tests.append(fmt(['ZZZ9999'] * (N - 1) + ['AAA0000']))
    return tests

